import {audioPreferences} from './audio-preferences.mjs';
import {redeemSavedGift,REDEEM_REWARDS} from './redeem-codes.mjs';
import {itemInfo} from './campaign-growth-data.mjs';
const rects={on:[29,149,458,239],off:[540,149,458,239],rail:[1035,215,473,106],thumb:[163,629,181,264],gift:[1098,602,355,332]};
function art(name){const [x,y,w,h]=rects[name];return `background-image:url('assets/settings/settings-controls-v1.png');background-size:${1536/w*100}% ${1024/h*100}%;background-position:${x/(1536-w)*100}% ${y/(1024-h)*100}%;`;}
const rows=[['enabled','volume','总声音','控制游戏中的全部声音'],['effectsEnabled','effectsVolume','战斗音效','施法、命中与机关反馈'],['musicEnabled','musicVolume','背景音乐','安静的月下旋律与秘境行旅']];
export class SettingsDialog{
 constructor({storage,onSave=()=>{}}={}){this.storage=storage;this.onSave=onSave;this.prefs=audioPreferences();this.el=document.createElement('dialog');this.el.className='realm-settings';this.el.setAttribute('aria-labelledby','settings-title');this.el.innerHTML=`<div class="settings-shell"><button class="settings-close" aria-label="关闭设置">×</button><h2 id="settings-title">秘境设置</h2><nav class="settings-tabs" aria-label="设置分类"><button data-tab="audio" aria-pressed="true">声音与音乐</button><button data-tab="gift" aria-pressed="false">兑换馈赠</button></nav><div class="settings-content"><section data-pane="audio" class="audio-settings">${rows.map(([enabled,volume,name,copy])=>`<div class="settings-audio-row"><div><h3>${name}</h3><p>${copy}</p></div><button type="button" class="painted-toggle" data-toggle="${enabled}" aria-label="${name}" aria-pressed="true"></button><label class="painted-range"><span class="sr-only">${name}音量</span><i class="volume-rail" style="${art('rail')}"></i><i class="volume-marker" style="${art('thumb')}"></i><input data-volume="${volume}" aria-label="${name}音量" type="range" min="0" max="100" step="1"><output></output></label></div>`).join('')}</section><section data-pane="gift" hidden><form class="gift-form"><label for="realm-gift-code">兑换码</label><div><input id="realm-gift-code" placeholder="输入获得的兑换码" autocomplete="off" maxlength="40" spellcheck="false"><button type="submit">领取馈赠</button></div></form><div class="gift-preview"><i style="${art('gift')}" aria-hidden="true"></i><div><h3>旅人的秘境馈赠</h3><p>奖励保存至本机进度，每份馈赠可领取一次。</p><div class="gift-rewards">${REDEEM_REWARDS.map(item=>{const d=itemInfo(item),x=d.icon%4,y=Math.floor(d.icon/4);return `<span><i style="background-image:url('assets/campaign-growth/items-v1.png');background-size:400% 400%;background-position:${x/3*100}% ${y/3*100}%"></i><b>${d.name} ×${item.count}</b></span>`;}).join('')}</div></div></div></section></div><p class="settings-status" role="status" aria-live="polite">设置自动保存于当前设备</p><button class="settings-done">返回旅程</button><button class="realm-exit-button" data-exit-app hidden>退出游戏</button></div>`;
 document.body.append(this.el);this.el.querySelector('.settings-close').onclick=()=>this.el.close();this.el.querySelector('.settings-done').onclick=()=>this.el.close();this.el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{this.el.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));this.el.querySelectorAll('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.tab);});this.el.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>this.change({[b.dataset.toggle]:!this.prefs.value[b.dataset.toggle]}));this.el.querySelectorAll('[data-volume]').forEach(input=>input.addEventListener('input',()=>this.change({[input.dataset.volume]:Number(input.value)/100})));this.el.querySelector('.gift-form').onsubmit=e=>{e.preventDefault();this.redeem();};this.prefs.subscribe(()=>this.render());this.render();}
 status(message){this.el.querySelector('.settings-status').textContent=message;}
 change(patch){this.status(this.prefs.update(patch)?'设置已保存':'声音设置已生效，当前设备暂时无法保存');}
 render(){const p=this.prefs.value;this.el.querySelectorAll('[data-toggle]').forEach(b=>{b.setAttribute('aria-pressed',String(p[b.dataset.toggle]));b.style.cssText=art(p[b.dataset.toggle]?'on':'off');});this.el.querySelectorAll('[data-volume]').forEach(input=>{const n=Math.round(p[input.dataset.volume]*100);input.value=n;input.closest('label').querySelector('output').textContent=n+'%';input.closest('label').querySelector('.volume-marker').style.left=`calc(${n}% + ${12-.74*n}px)`;});}
 redeem(){try{const next=redeemSavedGift(this.storage,this.el.querySelector('#realm-gift-code').value);this.onSave(next);this.status('兑换成功：5张抽奖券已到账，3个大金币宝箱与3瓶大角色经验药水已放入背包。');this.el.querySelector('#realm-gift-code').value='';}catch(error){this.status(error.message);}}
 open(){this.render();this.status('设置自动保存于当前设备');this.el.showModal();}
}
